<?php require_student();$me=student();$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$password=$_POST['password']??'';if(strlen($name)<2)$errors[]='Enter a valid name.';if($password!==''&&strlen($password)<8)$errors[]='New password must contain at least 8 characters.';if(!$errors){if($password!==''){$hash=password_hash($password,PASSWORD_DEFAULT);$stmt=db()->prepare('UPDATE students SET name=?,phone=?,password=? WHERE id=?');$stmt->bind_param('sssi',$name,$phone,$hash,$me['id']);}else{$stmt=db()->prepare('UPDATE students SET name=?,phone=? WHERE id=?');$stmt->bind_param('ssi',$name,$phone,$me['id']);}$stmt->execute();$_SESSION['student']['name']=$name;flash('success','Profile updated successfully.');redirect('student/profile.php');}}$pageTitle='My Profile';require_once __DIR__.'/../includes/header.php'; ?>
<div class="row g-4"><div class="col-lg-3"><?php require __DIR__.'/_sidebar.php'; ?></div><div class="col-lg-9"><div class="dashboard-header mb-4"><div class="small-muted">STUDENT PORTAL</div><h1 class="section-title mb-0">My profile</h1></div><div class="card"><div class="card-body"><p class="small-muted">Your student ID and email are used for identification and cannot be changed here.</p><?php if($errors): ?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $item): ?><li><?=e($item)?></li><?php endforeach;?></ul></div><?php endif; ?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Student ID</label><input class="form-control" value="<?=e($me['student_id'])?>" disabled></div><div class="col-md-6"><label class="form-label">Email</label><input class="form-control" value="<?=e($me['email'])?>" disabled></div><div class="col-md-6"><label class="form-label">Full name</label><input class="form-control" name="name" required value="<?=e($me['name'])?>"></div><div class="col-md-6"><label class="form-label">Phone</label><input class="form-control" name="phone" value="<?=e($me['phone']??'')?>"></div><div class="col-12"><label class="form-label">New password <span class="small-muted">(leave blank to keep current password)</span></label><input class="form-control" type="password" name="password" minlength="8"></div></div><button class="btn btn-primary mt-4">Save changes</button></form></div></div></div></div>
